    import { feeConfig } from './config';
    // ... existing utils
    export function calculateTransactionFee(transactionAmount: number): number {
      const percentageFee = transactionAmount * feeConfig.percentage;
      const finalFee = Math.max(percentageFee, feeConfig.minimumFee);
      return parseFloat(finalFee.toFixed(2)); // Ensure currency-friendly rounding
    }
    ```
